import {animate} from './vendor/anime.esm.min.js';
import {createBrand} from './brand.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const mediaQuery=matchMedia('(prefers-reduced-motion: reduce)');
let reduced=mediaQuery.matches, original=false, muted=true;
const defaults={brightness:85,contrast:90,volume:35,compression:true,notices:true};
let settings={...defaults},saved=false;
try{const data=JSON.parse(localStorage.getItem('pariview-fit-v1'));if(data&&data.settings){for(const key of ['brightness','contrast','volume']){if(Number.isFinite(data.settings[key]))settings[key]=data.settings[key];}for(const key of ['compression','notices']){if(typeof data.settings[key]==='boolean')settings[key]=data.settings[key];}settings.brightness=Math.max(45,Math.min(100,settings.brightness));settings.contrast=Math.max(65,Math.min(110,settings.contrast));settings.volume=Math.max(0,Math.min(70,settings.volume));saved=true;}}catch{}
const video=$('#film');const studio={setLook(){},reset(){},ready:true};createBrand($('#brand-symbol'),()=>reduced).catch(()=>{});createBrand($('#brand-wordmark'),()=>reduced).catch(()=>{});
let audioContext,source,gain,compressor,analyser,audioRoute='';
const notify=(message)=>{$('#toast').textContent=message;gsap.killTweensOf('#toast');gsap.to('#toast',{opacity:1,y:-5,duration:reduced?0:.2});gsap.to('#toast',{opacity:0,y:0,duration:.3,delay:3});};
function initAudio(){if(audioContext){audioContext.resume();return;}const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;audioContext=new AC();source=audioContext.createMediaElementSource(video);gain=audioContext.createGain();compressor=audioContext.createDynamicsCompressor();compressor.threshold.value=-25;compressor.knee.value=22;compressor.ratio.value=5;compressor.attack.value=.008;compressor.release.value=.25;analyser=audioContext.createAnalyser();analyser.fftSize=256;gain.connect(analyser);analyser.connect(audioContext.destination);routeAudio();audioContext.resume();}
function routeAudio(){if(!source)return;const route=(!original&&settings.compression)?'compressed':'original';if(audioRoute!==route){source.disconnect();compressor.disconnect();if(route==='compressed'){source.connect(compressor);compressor.connect(gain);}else source.connect(gain);audioRoute=route;}gain.gain.setTargetAtTime(settings.volume/100,audioContext.currentTime,.08);}
function fillRange(el){el.style.setProperty('--pct',100*(Number(el.value)-Number(el.min))/(Number(el.max)-Number(el.min))+'%');}
function reflect(){for(const key of ['brightness','contrast','volume']){$('#'+key).value=settings[key];$('#'+key+'-value').value=settings[key]+'%';fillRange($('#'+key));}for(const key of ['compression','notices']){$('#'+key).classList.toggle('on',settings[key]);$('#'+key).setAttribute('aria-checked',String(settings[key]));}$('#custom-mode').classList.toggle('active',!original);$('#original-mode').classList.toggle('active',original);$('#custom-mode').setAttribute('aria-pressed',String(!original));$('#original-mode').setAttribute('aria-pressed',String(original));$('#profile-state').textContent=saved?'내 설정이 저장되어 있어요':'아직 피팅 전이에요';$('#fit-status').textContent=original?'원본 비교':saved?'나의 설정':'예시 설정';studio.setLook(original?1:settings.brightness/100,original?1:settings.contrast/100,original);video.style.filter=original?'none':`brightness(${settings.brightness}%) contrast(${settings.contrast}%)`;routeAudio();if(!settings.notices){$('#event-notice').hidden=true;$('#view-event-notice').hidden=true;}}
reflect();
for(const key of ['brightness','contrast','volume'])$('#'+key).addEventListener('input',e=>{settings[key]=Number(e.target.value);original=false;reflect();});
for(const key of ['compression','notices'])$('#'+key).addEventListener('click',()=>{settings[key]=!settings[key];original=false;reflect();});
$('#custom-mode').onclick=()=>{original=false;reflect();};$('#original-mode').onclick=()=>{original=true;reflect();notify('원본 화면과 음량 변화를 비교합니다 전체 음량은 유지됩니다');};
function save(){try{localStorage.setItem('pariview-fit-v1',JSON.stringify({settings,updatedAt:new Date().toISOString()}));saved=true;reflect();notify('지금의 편안한 기준을 이 브라우저에 저장했어요');}catch{notify('브라우저 저장 공간을 사용할 수 없어요 현재 설정은 계속 적용됩니다');}}
$('#save-settings').onclick=save;
function renderPlay(){$('#play-button').setAttribute('aria-label',video.paused?'영상 재생':'영상 일시정지');$('#play-button use').setAttribute('href',video.paused?'#i-play':'#i-pause');}
$('#play-button').onclick=async()=>{if(video.paused){try{if(!muted)initAudio();await video.play();}catch{notify('영상 재생을 시작하지 못했어요 다시 눌러주세요');}}else video.pause();renderPlay();};
$('#mute-button').onclick=()=>{muted=!muted;if(!muted)initAudio();video.muted=muted;$('#mute-button').setAttribute('aria-pressed',String(muted));$('#mute-button').setAttribute('aria-label',muted?'음소거 해제':'음소거');$('#mute-label').textContent=muted?'OFF':'ON';};
function initialFrame(){video.currentTime=0;$('#seek').max=video.duration;$('#duration').textContent=formatTime(video.duration);}
video.addEventListener('loadedmetadata',initialFrame);if(video.readyState>=1)initialFrame();
function formatTime(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(Math.floor(s%60)).padStart(2,'0');}
const events=[{at:2.6,end:4,type:'소리 변화'},{at:5.0,end:6.7,type:'빛 변화'},{at:8.0,end:9.6,type:'소리 변화'},{at:10.1,end:11.3,type:'빛 변화'}];
function updateTime(){const t=video.currentTime,d=video.duration||24;$('#current-time').textContent=formatTime(t);$('#seek').value=t;fillRange($('#seek'));$('.track-playhead').style.left=`calc(32px + (100% - 32px) * ${t/d})`;const next=events.find(e=>e.at>=t&&e.at-t<=3);const notice=$('#event-notice');if(next&&settings.notices&&!video.paused){notice.hidden=false;$('#event-notice-text').textContent=`${Math.max(1,Math.ceil(next.at-t))}초 뒤 ${next.type} · 시연 구간`;}else notice.hidden=true;const viewing=$('#view-event-notice');viewing.hidden=notice.hidden;viewing.textContent=$('#event-notice-text').textContent;}
video.addEventListener('timeupdate',updateTime);video.addEventListener('play',renderPlay);video.addEventListener('pause',()=>{renderPlay();updateTime();});video.addEventListener('ended',()=>{renderPlay();notify('장면이 끝났어요 같은 장면을 다시 비교할 수 있어요');});video.addEventListener('error',()=>notify('영상 파일을 불러오지 못했어요 연결을 확인해 주세요'));
$('#seek').oninput=e=>{video.currentTime=Number(e.target.value);updateTime();};

$('#fullscreen-button').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.stage-card').requestFullscreen();}catch{notify('이 브라우저에서는 전체 화면을 지원하지 않아요');}};
function setMotion(value){reduced=value;document.body.classList.toggle('reduce-motion',value);$('#motion-toggle').setAttribute('aria-pressed',String(value));$('#motion-toggle').lastChild.textContent=value?'모션 줄이기 켜짐':'모션 줄이기';studio.reset();document.dispatchEvent(new Event('pariview-motion-change'));}
$('#motion-toggle').onclick=()=>setMotion(!reduced);mediaQuery.addEventListener('change',e=>setMotion(e.matches));setMotion(reduced);
function showTab(tab){video.pause();$('#studio-view').hidden=tab!=='studio';$('#research-view').hidden=tab!=='research';$('#page-name').textContent=tab==='studio'?'시청 스튜디오':'설계의 근거';$$('.nav-item[data-tab]').forEach(el=>el.classList.toggle('active',el.dataset.tab===tab));history.replaceState(null,'','#'+tab);window.scrollTo({top:0,behavior:reduced?'instant':'smooth'});if(!reduced)gsap.from(`#${tab}-view`,{opacity:.3,y:8,duration:.35,clearProps:'all'});}
$$('[data-tab]').forEach(el=>el.onclick=()=>showTab(el.dataset.tab));
const research=[
 {tag:'개인차 · 상황에 따른 변화',title:'‘정답 설정’은 하나가 아닙니다',text:'자폐 성인 49명의 혼합방법 설문에서 감각 경험의 개인차와 기분·피로, 통제의 중요성이 보고되었습니다',design:'소리와 빛을 각각 비교하고, 원할 때 다시 피팅하는 흐름을 제안합니다',ref:'MacLennan, O’Brien & Tavassoli (2022)',url:'https://doi.org/10.1007/s10803-021-05186-3'},
 {tag:'사용자의 통제권',title:'바꿀 수 있다는 감각까지',text:'자폐 아동 41명의 감각실 연구에서 직접 조절 조건의 주의집중 증가가 관찰됐습니다 불안 감소는 입증되지 않았으며 조건에 여러 차이가 있었습니다',design:'적용·건너뛰기·원본 복귀의 결정권을 사용자에게 둡니다',ref:'Unwin, Powell & Jones (2022)',url:'https://doi.org/10.1177/13623613211050176'},
 {tag:'시청각 영화 연구',title:'소리와 화면을 함께 봅니다',text:'7–14세 남아 46명의 영화 시청 연구에서 감각 특성 하위집단에 따른 신경반응 차이가 관찰됐습니다 주관적 과부하나 완화 효과를 직접 측정한 연구는 아닙니다',design:'소리·빛 변화 정보를 같은 시간축에서 확인하는 감각 지도를 제안합니다',ref:'Matsuzaki et al. (2022)',url:'https://doi.org/10.1016/j.braindev.2021.08.007'},
 {tag:'예고 단서에도 개인차',title:'미리 알림도 선택입니다',text:'자폐 55명·비자폐 28명의 청각·촉각 자극 연구에서 예고 단서에 대한 신경반응이 감각 과반응 수준과 관련됐습니다 영상 UI 효과를 검증한 연구는 아닙니다',design:'사전 안내는 강제하지 않고, 켜거나 끌 수 있게 설계합니다',ref:'Yosef et al. (2026)',url:'https://doi.org/10.1002/aur.70283'},
 {tag:'국내 보조 근거 · KCI',title:'덜 자극적이라고 늘 더 좋을까요?',text:'ADHD 아동 5명의 ABAB 연구에서 자연음을 사용한 백색소음 중재기에 주의집중과 암산 수행 향상이 보고됐습니다 소규모 교실 연구로 영상 시청에 일반화할 수 없습니다',design:'‘모든 자극 감소’를 기본 정답으로 두지 않고 개인 선택을 존중합니다',ref:'김경민 (2010), 정서·행동장애연구 26(3), 113–126',url:'https://www.kci.go.kr/kciportal/landing/article.kci?arti_id=ART001481865'},
 {tag:'배경 종설',title:'감각 차이에서 시작한 접근성',text:'자폐의 감각처리 차이를 다룬 종설은 감각 특성을 접근성 설계에서 고려할 배경을 제공합니다 특정 피팅 방식이나 제품 효과의 검증은 아닙니다',design:'진단명을 자동 설정값으로 바꾸기보다 개인의 선호를 묻습니다',ref:'Robertson & Baron-Cohen (2017)',url:'https://doi.org/10.1038/nrn.2017.112'}
];
$('#research-cards').innerHTML=research.map(r=>`<article class="research-card"><span class="tag">${r.tag}</span><h2>${r.title}</h2><p>${r.text}</p><p class="inference">설계 해석 → ${r.design}</p><a href="${r.url}" target="_blank" rel="noopener">${r.ref} ↗</a></article>`).join('');
// A mode is a starting point; comparisons explore current preference, never diagnosis.
const modes=[
 {id:'gentle',title:'자극을 편안하게',en:'Sensory Sensitive',icon:'moon',desc:'밝기와 소리 크기를 낮춰 시작해요',values:{brightness:75,contrast:85,volume:25,compression:true}},
 {id:'focus',title:'이야기에 집중',en:'Focus Support',icon:'play',desc:'소리의 변화 폭을 줄여 시작해요',values:{brightness:90,contrast:95,volume:30,compression:true}},
 {id:'clarity',title:'조금 더 또렷하게',en:'Clarity Assist',icon:'sun',desc:'화면의 밝기와 윤곽을 살려요',values:{brightness:100,contrast:105,volume:35,compression:false}},
 {id:'soft',title:'부드럽게 시작',en:'Soft Discovery',icon:'glasses',desc:'낮은 대비와 작은 소리로 살펴봐요',values:{brightness:80,contrast:80,volume:22,compression:true}},
 {id:'everyday',title:'평소처럼 편안하게',en:'Eye & Ear Ease',icon:'sound',desc:'기본 설정에서 조금씩 맞춰봐요',values:{brightness:85,contrast:90,volume:35,compression:true}}
];
const steps=[
 {key:'brightness',title:'어느 화면 밝기가 더 편한가요?',sub:'같은 장면을 다른 밝기로 비교해 보세요',a:65,b:90,an:'조금 어둡게',bn:'조금 밝게',kind:'visual'},
 {key:'contrast',title:'어느 쪽의 대비가 더 편한가요?',sub:'색과 윤곽이 느껴지는 정도를 골라보세요',a:78,b:105,an:'부드러운 대비',bn:'또렷한 대비',kind:'visual'},
 {key:'volume',title:'어느 소리 크기가 더 편한가요?',sub:'같은 장면을 4초씩 들어보세요 작은 소리부터 시작해요',a:22,b:45,an:'작은 소리',bn:'조금 큰 소리',kind:'audio'},
 {key:'compression',title:'소리의 변화를 어떻게 듣고 싶나요?',sub:'같은 장면에서 소리 크기의 차이를 비교해 보세요',a:true,b:false,an:'변화 폭을 줄여서',bn:'원본 변화 그대로',kind:'audio'}
];
let fitStep=0,answers=Array(4).fill(null),previewTimeout,returnFocus,fitBase,modeIndex=0,previewEpoch=0;
const phaseNav=phase=>`<div class="fit-steps"><span class="${phase===1?'current':''}"><i>01</i>기본 모드</span><span class="${phase===2?'current':''}"><i>02</i>장면 비교</span><span class="${phase===3?'current':''}"><i>03</i>시청 설정</span></div>`;
function fitOpen(){returnFocus=document.activeElement;video.pause();fitStep=0;answers=Array(4).fill(null);modeIndex=4;fitBase={...settings};$('#fit-dialog').showModal();renderModes();if(!reduced)gsap.fromTo('.fit-modal',{opacity:0,y:10},{opacity:1,y:0,duration:.25});}
function stopPreview(){previewEpoch++;clearTimeout(previewTimeout);$$('.fit-preview').forEach(v=>v.pause());video.pause();video.muted=muted;reflect();}
function fitClose(){stopPreview();$('#fit-dialog').close();returnFocus?.focus();}
$('#close-fit').onclick=fitClose;$('#fit-dialog').addEventListener('cancel',()=>{stopPreview();returnFocus?.focus();});$$('[data-action="fit"]').forEach(el=>el.onclick=fitOpen);
function renderModes(){stopPreview();gsap.set('#fit-progress-fill',{width:'10%'});$('#fit-body').innerHTML=phaseNav(1)+`<div class="fit-step-count">A PLACE TO START <span>1 / 3</span></div><h2 class="fit-heading">오늘은 어떻게 보고 싶나요?</h2><p class="fit-subtitle">가까운 모드를 골라주세요 다음 화면에서 소리와 빛을 하나씩 맞춰요</p><div class="mode-options">${modes.map((m,i)=>`<button class="mode-option ${i===modeIndex?'selected':''}" data-mode="${i}" aria-pressed="${i===modeIndex}"><svg><use href="#i-${m.icon}"/></svg><span class="mode-en">${m.en}</span><b>${m.title}</b><p>${m.desc}</p><span class="mode-check">${i===modeIndex?'✓ 선택했어요':'이 모드로 시작'}</span></button>`).join('')}</div><div class="fit-actions"><button class="back" id="mode-current">기존 설정에서 비교</button><button class="primary" id="start-comparison">장면 비교하기 <svg><use href="#i-arrow"/></svg></button></div><p class="fit-footnote">모드는 조절을 시작하기 위한 예시예요 특정 진단이나 연령에 맞춘 처방이 아닙니다</p>`;$$('[data-mode]').forEach(b=>b.onclick=()=>{modeIndex=Number(b.dataset.mode);renderModes();});$('#start-comparison').onclick=()=>{fitBase={...settings,...modes[modeIndex].values};fitStep=0;renderFit();};$('#mode-current').onclick=()=>{fitBase={...settings};fitStep=0;renderFit();};}
function renderFit(){stopPreview();const s=steps[fitStep];gsap.to('#fit-progress-fill',{width:(25+(fitStep+1)*15)+'%',duration:reduced?0:.2});const filter=value=>s.key==='brightness'?`brightness(${value}%) contrast(${fitBase.contrast}%)`:s.key==='contrast'?`brightness(${fitBase.brightness}%) contrast(${value}%)`:`brightness(${fitBase.brightness}%) contrast(${fitBase.contrast}%)`;
$('#fit-body').innerHTML=phaseNav(2)+`<div class="fit-step-count">SAME SCENE, TWO SETTINGS <span>${fitStep+1} / 4 비교</span></div><h2 class="fit-heading">${s.title}</h2><p class="fit-subtitle">${s.sub}</p><div class="ab-options">${['a','b'].map(key=>`<article class="ab-option ${answers[fitStep]===key?'selected':''}" data-choice-card="${key}"><div class="option-top"><strong>${key.toUpperCase()}</strong><span>${s[key+'n']}</span></div><video class="fit-preview" data-preview="${key}" src="assets/movie-hologram.mp4" poster="assets/hologram-still.jpg" preload="metadata" muted playsinline style="filter:${filter(s[key])}" aria-label="동일한 영화 장면 ${key.toUpperCase()}"></video><div class="option-bottom"><button data-listen="${key}">▶ ${key.toUpperCase()} ${s.kind==='audio'?'듣기':'보기'}</button><button class="choose" data-choose="${key}" aria-pressed="${answers[fitStep]===key}">${answers[fitStep]===key?'✓ 선택했어요':'이쪽이 더 편해요'}</button></div></article>`).join('')}</div><div class="fit-uncertain"><button id="choose-equal" class="${answers[fitStep]==='equal'?'selected':''}">비슷해요 / 잘 모르겠어요</button><button id="skip-step">건너뛰기</button></div><div class="fit-actions"><button id="fit-back" class="back">← 이전</button><button id="fit-next" class="primary" ${answers[fitStep]===null?'disabled':''}>${fitStep===3?'내 설정 확인':'다음으로'} <svg><use href="#i-arrow"/></svg></button></div><p class="fit-footnote">지금의 선호를 알아보는 과정이에요 불편하면 언제든 종료해 주세요<br>감각 역치를 측정하는 검사는 아닙니다</p>`;
$$('[data-choose]').forEach(b=>b.onclick=()=>{answers[fitStep]=b.dataset.choose;renderFit();});$('#choose-equal').onclick=()=>{answers[fitStep]='equal';renderFit();};$('#skip-step').onclick=()=>{answers[fitStep]='skip';advance();};$('#fit-back').onclick=()=>{if(fitStep===0)renderModes();else{fitStep--;renderFit();}};$('#fit-next').onclick=advance;
$$('[data-listen]').forEach(b=>b.onclick=async()=>{stopPreview();const epoch=previewEpoch;const key=b.dataset.listen,preview=$(`[data-preview="${key}"]`);preview.currentTime=5;preview.muted=true;if(s.kind==='audio'){initAudio();if(!audioContext){notify('이 브라우저에서는 소리 비교를 사용할 수 없어요');return;}video.currentTime=5;video.muted=false;source.disconnect();compressor.disconnect();const val=s[key],compressed=s.key==='compression'?val:fitBase.compression;if(compressed){source.connect(compressor);compressor.connect(gain);audioRoute='compressed';}else{source.connect(gain);audioRoute='original';}gain.gain.setValueAtTime((s.key==='volume'?val:Math.min(fitBase.volume,35))/100,audioContext.currentTime);}
try{await preview.play();if(s.kind==='audio')await video.play();if(epoch!==previewEpoch){preview.pause();video.pause();return;}b.textContent='■ 멈추기';b.onclick=()=>{stopPreview();renderFit();};previewTimeout=setTimeout(()=>{stopPreview();renderFit();},4000);}catch{stopPreview();notify('장면을 재생하지 못했어요 다시 눌러주세요');}});
}
function advance(){stopPreview();if(fitStep<3){fitStep++;renderFit();}else showResult();}
function getFitResult(){const result={...fitBase};steps.forEach((s,i)=>{if(answers[i]==='a'||answers[i]==='b')result[s.key]=s[answers[i]];});return result;}
function showResult(){const result=getFitResult();gsap.set('#fit-progress-fill',{width:'100%'});$('#fit-body').innerHTML=phaseNav(3)+`<div class="fit-result"><div class="result-mark"><svg><use href="#i-glasses"/></svg></div><div class="kicker">YOUR FIT, FOR TODAY</div><h2>오늘의 시청 설정이<br>준비됐어요</h2><p>고른 값을 반영했어요 비슷하거나 건너뛴 항목은 시작 설정을 유지합니다</p><div class="result-values"><div><small>화면 밝기</small><strong>${result.brightness}%</strong></div><div><small>화면 대비</small><strong>${result.contrast}%</strong></div><div><small>전체 음량</small><strong>${result.volume}%</strong></div><div><small>음량 변화 완화</small><strong>${result.compression?'켜짐':'꺼짐'}</strong></div></div><button id="apply-fit" class="primary">이 설정으로 시청하기<svg><use href="#i-arrow"/></svg></button><button id="result-back" class="back">← 이전 비교로 돌아가기</button><p class="fit-footnote">편안함이 달라지면 다시 맞춰주세요<br>결과는 최적·안전 판정이 아닌, 선택에 따른 시청 설정입니다</p></div>`;$('#apply-fit').onclick=()=>{settings=result;original=false;save();fitClose();showTab('studio');$('#watch-studio').scrollIntoView({behavior:'instant'});};$('#result-back').onclick=()=>{fitStep=3;renderFit();};}
if(location.hash==='#research')showTab('research');
window.__pariview={get settings(){return {...settings}},get original(){return original},get audioRoute(){return audioRoute},get muted(){return muted},get reduced(){return reduced},video,openFit:fitOpen};

// Subtle scroll transitions keep the actual viewing interface in focus.
const introMotion={p:0};const introTween=animate(introMotion,{p:1,duration:1000,ease:'linear',autoplay:false,onUpdate:()=>{if(reduced)return;const h=document.querySelector('.approved-hero');h.style.opacity=1-introMotion.p*.18;h.style.transform=`translateY(${-introMotion.p*12}px)`;}});window.addEventListener('scroll',()=>{const h=document.querySelector('.approved-hero');if(!h||reduced)return;introTween.seek(Math.min(1,Math.max(0,scrollY/Math.max(h.offsetHeight,1)))*1000);},{passive:true});
